public static int calculateTimeNeeded(int N) {
    if (N == 0) {
        return 0;
    }
    int timeNeeded = 0;
    int[] seats = new int[N];
    for (int i = 0; i < N; i++) {
        seats[i] = i + 1;
    }
    int swapCount = 0;
    while (swapCount < N - 1) {
        for (int i = 0; i < N - 1; i++) {
            if (seats[i] > seats[i + 1]) {
                timeNeeded += seats[i + 1] / seats[i];
            }
        }
        swapCount++;
    }
    return timeNeeded;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    permuteHelper(nums, 0, result);
    return result;
}

private void permuteHelper(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(new ArrayList<Integer>(nums.length));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        permuteHelper(nums, start + 1, result);
        swap(nums, start, i);
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

