public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int[][] visited = new int[n][n];
    visited[start[0]][start[1]] = 1;

    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    while (!queue.isEmpty()) {
        int[] curr = queue.poll();
        if (curr[0] == end[0] && curr[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] neighbor : getNeighbors(curr, paths, visited)) {
            if (visited[neighbor[0]][neighbor[1]] == 0) {
                visited[neighbor[0]][neighbor[1]] = 1;
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

private static int[][] getNeighbors(int[] curr, int[][] paths, int[][] visited) {
    List<int[]> neighbors = new ArrayList<>();
    for (int[] path : paths) {
        if (path[0] == curr[0] && path[1] == curr[1] && visited[path[0]][path[1]] == 0) {
            neighbors.add(path);
        }
    }
    return neighbors.toArray(new int[neighbors.size()][2]);
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int sumLengths = word1.length() + word2.length();
    int gcd = getGCD(sumLengths, commonLetters);
    int numerator = commonLetters / gcd;
    int denominator = sumLengths / gcd;
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

public static int getGCD(int a, int b) {
