        return getGCD(b, a % b);
    }
}

public static String convertDatesToWeekdays(String date) {
    String[] dateParts = date.split(" ");
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);

    Calendar calendar = Calendar.getInstance();
    calendar.set(year, month - 1, day);

    int dayOfWeek = calendar.get(Calendar.DAY_OF_WEEK);
    String weekday = "";
    switch (dayOfWeek) {
        case Calendar.MONDAY:
            weekday = "Monday";
            break;
        case Calendar.TUESDAY:
            weekday = "Tuesday";
            break;
        case Calendar.WEDNESDAY:
            weekday = "Wednesday";
            break;
        case Calendar.THURSDAY:
            weekday = "Thursday";
            break;
        case Calendar.FRIDAY:
            weekday = "Friday";
            break;
        case Calendar.SATURDAY:
            weekday = "Saturday";
            break;
        case Calendar.SUNDAY:
            weekday = "Sunday";
            break;
    }

    return month + " " + day + ", " + year + " is a " + weekday;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    double[] sorted = Arrays.copyOf(arr, n);
    Arrays.sort(sorted);

    int cut = (int)Math.round(n * 0.05);
    double sum = 0;
    for (int i = cut; i < n - cut; i++) {
        sum += sorted[i];
    }

    return sum / (n - 2 * cut);
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    int[] modArr = new int[k];
    for (int i = 0; i < n; i++) {
        int mod = arr[i] % k;
        modArr[mod]++;
    }
    for (int i = 1; i <= k / 2; i++) {
        if (modArr[i] != modArr[k - i]) {
            return false;
        }
    }
    return true;
}

public String sortString(String s) {
    if (s == null || s.length() < 2) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        char smallest = s.charAt(0);
        int smallestIndex = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < smallest) {
                smallest = s.charAt(i);
                smallestIndex = i;
            }
        }
        result.append(smallest);
        s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);
    }
    return result.toString();
}

