private static boolean isSteppingNumber(int number) {
    int previousDigit = -1;
    while (number > 0) {
        int currentDigit = number % 10;
        if (currentDigit != previousDigit + 1 && currentDigit != previousDigit - 1) {
            return false;
        }
        previousDigit = currentDigit;
        number /= 10;
    }
    return true;
}

