public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 1;
                int horizontalLength = 1;
                int verticalLength = 1;
                int diagonalLength = 1;
                int antiDiagonalLength = 1;
                for (int k = i + 1; k < mat.length; k++) {
                    if (mat[k][j] == 1) {
                        horizontalLength++;
                    }
                }
                for (int k = j + 1; k < mat[0].length; k++) {
                    if (mat[i][k] == 1) {
                        verticalLength++;
                    }
                }
                for (int k = i + 1, l = j + 1; k < mat.length && l < mat[0].length; k++, l++) {
                    if (mat[k][l] == 1) {
                        diagonalLength++;
                    }
                }
                for (int k = i + 1, l = j - 1; k < mat.length && l >= 0; k++, l--) {
                    if (mat[k][l] == 1) {
                        antiDiagonalLength++;
                    }
                }
                currentLength = Math.max(horizontalLength, verticalLength);
                currentLength = Math.max(currentLength, diagonalLength);
                currentLength = Math.max(currentLength, antiDiagonalLength);
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }
    return maxLength;
}

