public static int squarePermutations(int[] A) {
    int len = A.length;
    int count = 0;

    for (int i = 0; i < len; i++) {
        int sum = 0;
        for (int j = i; j < len; j++) {
            sum += A[j];
            if (isSquare(sum)) {
                count++;
            }
        }
    }
    return count;
}

private static boolean isSquare(int sum) {
    int root = (int) Math.sqrt(sum);
    return root * root == sum;
}

public static int largestRectangleArea(int[] heights) {
    if (heights.length == 0) return 0;
    int largest = 0;
    Stack<Integer> stack = new Stack<>();
    int[] newHeights = new int[heights.length];
    System.arraycopy(heights, 0, newHeights, 0, heights.length);
    Arrays.sort(newHeights);
    for (int i = 0; i < newHeights.length; i++) {
        while (!stack.isEmpty() && newHeights[i] < newHeights[stack.peek()]) {
            int h = newHeights[stack.pop()];
            largest = Math.max(largest, h * (i - (stack.isEmpty() ? 0 : stack.peek() + 1)));
        }
        stack.push(i);
    }
    while (!stack.isEmpty()) {
        int h = newHeights[stack.pop()];
        largest = Math.max(largest, h * (newHeights.length - (stack.isEmpty() ? 0 : stack.peek() + 1)));
    }
    return largest;
}

