bool isBoomerang(int[][] points) {
    // Check if the given array has exactly 3 points
    if (points.length != 3) {
        return false;
    }

    // Check if the three points are distinct
    if (points[0] == points[1] || points[0] == points[2] || points[1] == points[2]) {
        return false;
    }

    // Calculate the slope of the line joining the first and second points
    double slope1 = (double)(points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);

    // Calculate the slope of the line joining the first and third points
    double slope2 = (double)(points[2][1] - points[0][1]) / (points[2][0] - points[0][0]);

    // Check if the slopes are equal
    if (slope1 == slope2) {
        return false;
    }

    // Check if the points are in the correct positions to form a boomerang
    if ((points[1][0] < points[0][0] && points[2][0] > points[0][0]) || (points[1][0] > points[0][0] && points[2][0] < points[0][0])) {
        return true;
    }

    return false;
}

public static int findNthUglyNumber(int n) {
		if (n < 1) return -1;
		int[] un = new int[n];
		int count = 1;
		un[0] = 1;
		for (int i = 2; i <= n; i++) {
		  int num = i;
		  int[] factors = findFactors(num);
		  if (factors.length == 0) {
			un[i-1] = num;
		  } else {
			int max = 0;
			for (int j = 0; j < factors.length; j++) {
			  if (factors[j] > max) {
				max = factors[j];
			  }
			}
			un[i-1] = max;
		  }
		}
		return un[n-1];
	}

private static int[] findFactors(int num) {
		List<Integer> factors = new ArrayList<>();
		for (int i = 2; i <= Math.sqrt(num); i++) {
		  if (num % i == 0) {
			factors.add(i);
			if (num / i != i) {
			  factors.add(num / i);
			}
		  }
		}
		return factors.toArray(new int[factors.size()]);
	}

public static int calculateEnergy(String s) {
    int energy = 0;
    char previous = 0;
    int count = 0;
    for (char c : s.toCharArray()) {
        if (c == previous) {
            count++;
        } else {
            previous = c;
            count = 1;
        }
        if (count > energy) {
            energy = count;
        }
    }
    return energy;
}

